/// Mathematical definition of triangular number: sum of integers from 1 to n
/// triangle(0) = 0
/// triangle(n) = n + triangle(n-1) for n > 0
fn triangle(n: u32) -> u32 {
    n * (n + 1) / 2
}

/// Proof that triangular number function is monotonic:
/// For any i ≤ j, triangle(i) ≤ triangle(j)
/// This follows from the definition since triangle(n) = n*(n+1)/2 is
/// a strictly increasing function for n ≥ 0
fn triangle_is_monotonic(i: u32, j: u32) -> bool {
    // Implementation showing the property holds
    if i <= j {
        triangle(i) <= triangle(j)
    } else {
        true // vacuously true when i > j
    }
}

/// Tail-recursive procedure to compute triangular number
/// Preconditions:
/// - n: target non-negative integer
/// - idx: current index (0 ≤ idx ≤ n)
/// - sum: initially holds triangle(idx)
/// - All intermediate values fit in u32 (no overflow)
/// Postcondition:
/// - sum will contain triangle(n) when function returns
/// Recursion measure: n - idx (strictly decreasing each step)
fn tail_triangle(n: u32, idx: u32, sum: &mut u32) {
    // Base case: we've reached the target
    if idx == n {
        return;
    }
    
    // Recursive case: add next number and continue
    let next_idx = idx + 1;
    *sum += next_idx;
    
    // Tail-recursive call with updated values
    tail_triangle(n, next_idx, sum);
}

// Alternative iterative version that avoids recursion limits
fn tail_triangle_iterative(n: u32, idx: u32, sum: &mut u32) {
    let mut current = idx;
    let mut current_sum = *sum;
    
    while current < n {
        current += 1;
        current_sum += current;
    }
    
    *sum = current_sum;
}

